-- Four representative source records only: MOF_001, MOF_002, MOF_011, MOF_012.
-- No schema or RLS changes. Existing UUID column uses stable UUIDv5 mappings.
-- Exact original IDs, domains and review strings remain in content_body.original_metadata.
-- Multi-domain records use their first domain in the existing single-domain column.
-- approved_for_build -> APPROVED; expert_review -> IN_REVIEW; no reviewer invented.
-- Exact reruns are no-ops; conflicting existing records cause a full rollback.
begin;
lock table public.explore_content in share row exclusive mode;
do $import$
declare
 batch jsonb := $batch$[{"content_id": "b1dffb38-ab9c-5663-98cc-11f02b6e453d", "content_type": "MYTH_OR_FACT", "title": "High heat destroys gluten.", "subtitle": null, "domain": "KNOW", "topic": "Food & Safety", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_001", "domains": ["KNOW"], "original_metadata": {"content_id": "MOF_001", "content_type": "MYTH_OR_FACT", "statement": "High heat destroys gluten.", "answer_type": "MYTH", "domain": "KNOW", "topic": "Food & Safety", "xp_value": "+5", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Gluten is not made safe simply by cooking at a high temperature. For example, food fried in oil shared with gluten-containing foods can be exposed through cross-contact.", "takeaway": "Heat is not a reliable way to make gluten-containing or cross-contacted food appropriate for celiac disease.", "source_organization": "Beyond Celiac / Celiac Disease Foundation", "source_url": "https://www.beyondceliac.org/gluten-free-diet/cross-contact/", "review_note": null}}, "choices": [], "feedback": {"answer_type": "MYTH", "summary": "Gluten is not made safe simply by cooking at a high temperature. For example, food fried in oil shared with gluten-containing foods can be exposed through cross-contact."}, "teaching_point": "Heat is not a reliable way to make gluten-containing or cross-contacted food appropriate for celiac disease.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Beyond Celiac / Celiac Disease Foundation", "source_title": null, "source_url": "https://www.beyondceliac.org/gluten-free-diet/cross-contact/", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "a6c838eb-4636-5d32-b05d-a8381c32872a", "content_type": "MYTH_OR_FACT", "title": "Potatoes are naturally gluten-free.", "subtitle": null, "domain": "KNOW", "topic": "Food & Safety", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_002", "domains": ["KNOW"], "original_metadata": {"content_id": "MOF_002", "content_type": "MYTH_OR_FACT", "statement": "Potatoes are naturally gluten-free.", "answer_type": "FACT", "domain": "KNOW", "topic": "Food & Safety", "xp_value": "+5", "review_status": "approved_for_build", "expert_reviewed": "not required for coding", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Plain potatoes are naturally gluten-free. What happens during preparation still matters; added ingredients or cross-contact can change the situation.", "takeaway": "Naturally gluten-free does not automatically mean every prepared version is gluten-free.", "source_organization": "NIDDK", "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "review_note": null}}, "choices": [], "feedback": {"answer_type": "FACT", "summary": "Plain potatoes are naturally gluten-free. What happens during preparation still matters; added ingredients or cross-contact can change the situation."}, "teaching_point": "Naturally gluten-free does not automatically mean every prepared version is gluten-free.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "NIDDK", "source_title": null, "source_url": "https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/eating-diet-nutrition", "author": null, "review_status": "APPROVED", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "49d67dcd-1e74-540b-91b3-9be9fb5d9122", "content_type": "MYTH_OR_FACT", "title": "If my friends change restaurants because of me, I'm being difficult.", "subtitle": null, "domain": "LIVE", "topic": "Belonging", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_011", "domains": ["LIVE", "SPEAK"], "original_metadata": {"content_id": "MOF_011", "content_type": "MYTH_OR_FACT", "statement": "If my friends change restaurants because of me, I'm being difficult.", "answer_type": "LETS_RETHINK_IT", "domain": "LIVE, SPEAK", "topic": "Belonging", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Having a medical dietary need does not automatically make you difficult. Friends may genuinely want to choose somewhere everyone can participate. You can also decide together what works for the group.", "takeaway": "Being included is not the same as being a burden.", "source_organization": "Teen lived-experience synthesis; expert review required", "source_url": null, "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "LETS_RETHINK_IT", "summary": "Having a medical dietary need does not automatically make you difficult. Friends may genuinely want to choose somewhere everyone can participate. You can also decide together what works for the group."}, "teaching_point": "Being included is not the same as being a burden.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Teen lived-experience synthesis; expert review required", "source_title": null, "source_url": null, "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}, {"content_id": "b8b17062-b8e7-548c-b7ee-fbd3ffa45888", "content_type": "MYTH_OR_FACT", "title": "Bringing my own food is always the best solution.", "subtitle": null, "domain": "MANAGE", "topic": "Planning", "interaction_type": "CHOICE", "difficulty": null, "estimated_minutes": null, "intro": null, "content_body": {"format": "myth_or_fact_v1", "content_id": "MOF_012", "domains": ["MANAGE", "LIVE"], "original_metadata": {"content_id": "MOF_012", "content_type": "MYTH_OR_FACT", "statement": "Bringing my own food is always the best solution.", "answer_type": "IT_DEPENDS", "domain": "MANAGE, LIVE", "topic": "Planning", "xp_value": "+5", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "explanation": "Bringing food can be a useful backup, but it is only one strategy. Depending on the situation, you might research options, ask questions, eat beforehand, suggest another place, bring something, or combine approaches.", "takeaway": "Good self-management can look different in different situations.", "source_organization": "Celiac Disease Foundation + teen lived-experience extension", "source_url": "https://celiac.org/dining-and-social-eating/", "review_note": "Keep this item flagged for expert review before public release. It translates evidence and/or teen lived experience into self-management content."}}, "choices": [], "feedback": {"answer_type": "IT_DEPENDS", "summary": "Bringing food can be a useful backup, but it is only one strategy. Depending on the situation, you might research options, ask questions, eat beforehand, suggest another place, bring something, or combine approaches."}, "teaching_point": "Good self-management can look different in different situations.", "next_step": null, "related_content_ids": [], "xp_value": 5, "source_type": "EDITORIAL", "source_organization": "Celiac Disease Foundation + teen lived-experience extension", "source_title": null, "source_url": "https://celiac.org/dining-and-social-eating/", "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}]$batch$::jsonb;
 wanted jsonb; code text; incoming public.explore_content%rowtype; current_row public.explore_content%rowtype;
begin
 for wanted in select value from jsonb_array_elements(batch) loop
  code := wanted->'content_body'->>'content_id';
  select * into incoming from jsonb_populate_record(null::public.explore_content,wanted);
  if exists(select 1 from public.explore_content where content_body->>'content_id'=code and content_id<>incoming.content_id) then
   raise exception '% already uses a different UUID. No changes made.',code;
  end if;
  select * into current_row from public.explore_content where content_id=incoming.content_id for update;
  if found then
   if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then
    raise exception '% already exists with different fields. No changes made.',code;
   end if;
   continue;
  end if;
  insert into public.explore_content (content_id, content_type, title, subtitle, domain, topic, interaction_type, difficulty, estimated_minutes, intro, content_body, choices, feedback, teaching_point, next_step, related_content_ids, xp_value, source_type, source_organization, source_title, source_url, author, review_status, expert_reviewer, medical_review_required, content_version, last_reviewed, active) values (incoming.content_id, incoming.content_type, incoming.title, incoming.subtitle, incoming.domain, incoming.topic, incoming.interaction_type, incoming.difficulty, incoming.estimated_minutes, incoming.intro, incoming.content_body, incoming.choices, incoming.feedback, incoming.teaching_point, incoming.next_step, incoming.related_content_ids, incoming.xp_value, incoming.source_type, incoming.source_organization, incoming.source_title, incoming.source_url, incoming.author, incoming.review_status, incoming.expert_reviewer, incoming.medical_review_required, incoming.content_version, incoming.last_reviewed, incoming.active);
 end loop;
end $import$;
commit;
select content_body->>'content_id' as card_id,content_id,title as statement,feedback->>'answer_type' as answer_type,
 content_body->'original_metadata'->>'domain' as domains,topic,xp_value,
 content_body->'original_metadata'->>'review_status' as original_review_status,
 content_body->'original_metadata'->>'expert_reviewed' as original_expert_reviewed,
 review_status,medical_review_required,content_version,active
from public.explore_content where content_id in ('b1dffb38-ab9c-5663-98cc-11f02b6e453d'::uuid,'a6c838eb-4636-5d32-b05d-a8381c32872a'::uuid,'49d67dcd-1e74-540b-91b3-9be9fb5d9122'::uuid,'b8b17062-b8e7-548c-b7ee-fbd3ffa45888'::uuid) order by card_id;
